// GitHub churn by area (#402) — ranked horizontal-bar breakdown of lines changed per code area.
// Extracted from GitHubPulse's inline card into its own composable record; adds the loading skeleton
// the inline version didn't have.
import { CardHead, HBars, fmt } from "@/shared/ui/charts";
import { SkeletonChart } from "@/shared/ui/feedback/Skeleton";
import { Text } from "@/shared/ui/typography/Text";
import { Card } from "@/shared/ui/data/Card";

export interface ChurnArea { area: string; add: number; del: number; files: number; color: string }

const DEMO_AREAS: ChurnArea[] = [
  { area: "src/features/fleet", add: 820, del: 240, files: 9, color: "var(--accent)" },
  { area: "src/features/github", add: 610, del: 180, files: 7, color: "var(--info)" },
  { area: "src/shared/ui", add: 340, del: 90, files: 12, color: "var(--success)" },
];

export function ChurnByArea({ areas = DEMO_AREAS, loading = false }: { areas?: ChurnArea[]; loading?: boolean }) {
  if (loading) {
    return (
      <Card>
        <CardHead title="Churn by area" hint="lines changed · recent commits" />
        <SkeletonChart height={90} />
      </Card>
    );
  }
  if (!areas.length) return null;
  const rows = areas.map((a) => ({
    label: a.area, value: a.add + a.del, color: a.color, strong: true,
    tag: <Text as="span" mono size={9} tone="dim">
      <Text as="span" tone="success">+{fmt(a.add)}</Text> / <Text as="span" tone="danger">-{fmt(a.del)}</Text> · {a.files}f
    </Text>,
  }));
  return (
    <Card>
      <CardHead title="Churn by area" hint="lines changed · recent commits" />
      <HBars rows={rows} fmtV={(v) => fmt(v)} />
    </Card>
  );
}
